package com.y9pro.v5;

/**
 * No secrets live in the source tree. These values are injected at build time from keys.properties
 * (generated by tools/y9tool.py init, ignored by git) through Gradle's BuildConfig.
 */
final class Keys {
    private Keys() {}

    static final String CONFIG_URL = BuildConfig.CONFIG_URL;
    static final String SIGN_PUBLIC_KEY_B64 = BuildConfig.SIGN_PUBLIC_KEY_B64;
    static final String AES_KEY_B64 = BuildConfig.AES_KEY_B64;
}
